/* ── boy or girl: one guess per phone, kept on cinorev.in so every guest sees the same live count ── */
const pollSec = $("poll"), VOTE_KEY = "bs-vote:" + POLL.id;
let myVote = null, counts = null, pollAsked = false;
try { myVote = FMI.storage.getItem(VOTE_KEY); } catch (e) {}
function token(){
  let t = null; try { t = FMI.storage.getItem("bs-token"); } catch (e) {}
  if (!t) { t = (crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36) + Math.random().toString(36).slice(2)).replace(/[^A-Za-z0-9-]/g, ""); try { FMI.storage.setItem("bs-token", t); } catch (e) {} }
  return t;
}
function paintPoll(){
  if (!pollSec) return;
  ["g", "b"].forEach(k => { const b = $("v-" + k), mine = myVote === b.dataset.v; b.classList.toggle("mine", mine); b.setAttribute("aria-pressed", mine); });
  pollSec.classList.toggle("voted", !!myVote); pollSec.classList.toggle("counted", !!counts);
  const rt = $("r-t");
  if (!myVote) { rt.textContent = tr("tap6"); $("bar-g").style.width = $("bar-b").style.width = "50%"; $("pc-g").textContent = $("pc-b").textContent = ""; return; }
  const pick = tr(myVote === "girl" ? "girl" : "boy");
  if (counts) {
    const n = counts.girl + counts.boy, g = n ? Math.round(counts.girl / n * 100) : 50;
    $("bar-g").style.width = g + "%"; $("bar-b").style.width = (100 - g) + "%";
    $("pc-g").textContent = g + "%"; $("pc-b").textContent = (100 - g) + "%";
    rt.textContent = tr("youG").replace("%s", pick) + " " + (n === 1 ? tr("one") : tr("many").replace("%n", n.toLocaleString("en-IN"))) + ".";
  } else {
    $("pc-g").textContent = $("pc-b").textContent = "";
    rt.textContent = tr("youG").replace("%s", pick) + " " + tr("off");
  }
}
async function api(method, body){
  const r = await FMI.localResponse(POLL.api + (method === "GET" ? "?id=" + encodeURIComponent(POLL.id) : ""), { method, headers: body ? { "content-type": "application/json" } : {}, body: body ? JSON.stringify(body) : undefined, cache: "no-store" });
  const j = await r.json();
  if (j && typeof j.girl === "number" && (r.ok || r.status === 429)) return { girl: j.girl, boy: j.boy };   /* 429: too many new guesses from one connection; the count still shows */
  throw new Error((j && j.error) || r.status);
}
async function loadCounts(){ if (pollAsked || preview || !myVote) return; pollAsked = true; try { counts = await api("GET"); } catch (e) { counts = null; } paintPoll(); }
async function vote(v, el){
 if (FMI.voting) return; FMI.voting=true;
